package dev.luna.tools;
import dev.luna.runtime.BackgroundServices;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import com.google.gson.*;
public final class RuntimeSmokeCheck {
 static final HttpClient HTTP=HttpClient.newHttpClient();static JsonObject health(int port)throws Exception {return JsonParser.parseString(HTTP.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/health")).GET().build(),HttpResponse.BodyHandlers.ofString()).body()).getAsJsonObject();}
 public static void main(String[] args)throws Exception {Path temp=Files.createTempDirectory("luna java lifecycle spaces ");int port;try(var socket=new java.net.ServerSocket(0)){port=socket.getLocalPort();}var a=new BackgroundServices(temp.resolve("host"),port,System.out::println);var b=new BackgroundServices(temp.resolve("bot"),port,System.out::println);try{a.start().get(10,TimeUnit.SECONDS);if(!health(port).get("backend").getAsString().equals("java-in-process"))throw new AssertionError();b.start().get(10,TimeUnit.SECONDS);b.close();if(health(port).get("version").getAsInt()!=2)throw new AssertionError("Nonowner closed host backend");a.close();boolean stopped=false;for(int i=0;i<10;i++){try{health(port);}catch(java.net.ConnectException e){stopped=true;break;}Thread.sleep(100);}if(!stopped)throw new AssertionError("Owner shutdown failed");System.out.println("PASS: in-process Java service startup, reuse, nonowner shutdown and owner cleanup. No helper process was launched.");}finally{a.close();b.close();try(var files=Files.walk(temp)){for(Path p:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}
}
